#!/usr/bin/env node
/**
 * Generates data/json/bundle.js from the JSON files beside it.
 *
 * The JSON files are the source of truth. data/index.html loads them with
 * fetch(), which browsers block on file:// — so this writes a script that
 * assigns the same objects to window.ODDFOX_DATA as an offline fallback.
 *
 *   node tools/build-data-bundle.mjs
 *
 * Run it after editing anything in data/json/.
 */
import { readdirSync, readFileSync, writeFileSync, statSync } from 'node:fs';
import { join, dirname, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dir = join(root, 'data', 'json');
const OUT = 'bundle.js';

const files = readdirSync(dir).filter((f) => f.endsWith('.json')).sort();

const data = {};
let bad = 0;
for (const f of files) {
  const name = basename(f, '.json');
  try {
    data[name] = JSON.parse(readFileSync(join(dir, f), 'utf8'));
  } catch (err) {
    console.error(`  ✗ ${f} — ${err.message}`);
    bad++;
  }
}
if (bad) {
  console.error(`\n${bad} file(s) failed to parse. Bundle not written.`);
  process.exit(1);
}

// --- integrity: every source_id / area_id / incident_id must resolve ---
const sourceIds = new Set((data.sources?.records ?? []).map((r) => r.id));
const incidentIds = new Set((data.incidents?.records ?? []).map((r) => r.id));
const areaIds = new Set((data.chokepoints?.records ?? []).map((r) => r.id));

const problems = [];
const walk = (node, path) => {
  if (Array.isArray(node)) return node.forEach((v, i) => walk(v, `${path}[${i}]`));
  if (!node || typeof node !== 'object') return;
  for (const [k, v] of Object.entries(node)) {
    const at = `${path}.${k}`;
    if (k === 'source_id' && typeof v === 'string' && !sourceIds.has(v)) {
      problems.push(`${at} → unknown source "${v}"`);
    } else if (k === 'source_ids' && Array.isArray(v)) {
      v.filter((x) => !sourceIds.has(x)).forEach((x) => problems.push(`${at} → unknown source "${x}"`));
    } else if (k === 'area_id' && typeof v === 'string' && !areaIds.has(v)) {
      problems.push(`${at} → unknown chokepoint "${v}"`);
    } else if (k === 'incident_ids' && Array.isArray(v)) {
      v.filter((x) => !incidentIds.has(x)).forEach((x) => problems.push(`${at} → unknown incident "${x}"`));
    } else {
      walk(v, at);
    }
  }
};
for (const [name, d] of Object.entries(data)) walk(d, name);

if (problems.length) {
  console.error('Broken cross-references:');
  problems.forEach((p) => console.error(`  \u2717 ${p}`));
  console.error('\nBundle not written.');
  process.exit(1);
}

const body =
  `/* Generated by tools/build-data-bundle.mjs — do not edit.\n` +
  `   Source of truth is the .json files in this directory.\n` +
  `   Regenerate: node tools/build-data-bundle.mjs */\n` +
  `window.ODDFOX_DATA = ${JSON.stringify(data, null, 0)};\n`;

writeFileSync(join(dir, OUT), body);

// Cache-bust the asset links in index.html. python -m http.server and the
// firebase emulator both serve lib/*.css and lib/*.js with caching headers, so
// an edit would otherwise not show up without a hard refresh.
const idx = join(root, 'data', 'index.html');
try {
  const stamp = Math.max(
    ...['lib/oddfox.css', 'lib/oddfox.js'].map((f) => statSync(join(root, 'data', f)).mtimeMs)
  ).toFixed(0);
  let html = readFileSync(idx, 'utf8');
  const before = html;
  html = html
    .replace(/href="lib\/oddfox\.css(\?v=\d+)?"/, `href="lib/oddfox.css?v=${stamp}"`)
    .replace(/src="lib\/oddfox\.js(\?v=\d+)?"/, `src="lib/oddfox.js?v=${stamp}"`)
    .replace(/src="json\/bundle\.js(\?v=\d+)?"/, `src="json/bundle.js?v=${stamp}"`);
  if (html !== before) writeFileSync(idx, html);
  console.log(`asset links stamped v=${stamp}`);
} catch (err) {
  console.error(`could not stamp index.html: ${err.message}`);
}

const kb = (Buffer.byteLength(body) / 1024).toFixed(1);
console.log(`${files.length} datasets → data/json/${OUT} (${kb} KB)`);
for (const name of Object.keys(data)) {
  const d = data[name];
  const n = d.records?.length ?? d.datasets?.length ?? d.series?.length ?? '';
  console.log(`  ${name}${n ? ` — ${n} records` : ''}`);
}
